const fs = require\('fs'\);
for \(const line of fs.readFileSync\('.env.local','utf8'\).split\(/\\r?\\n/\)\) {
  const m = line.match\(/^\([A-Z_0-9]+\)=\(.*\)$/\);
  if \(m\) process.env[m[1]] = m[2].replace\(/^\\"|\\"$/g,''\);
}
fetch\('https://api.resend.com/emails', { headers: { Authorization: 'Bearer ' + process.env.SMTP_PASS } }\)
  .then\(r => r.json\(\)\)
  .then\(d => {
    const list = \(d.data || []\).slice\(0, 5\).map\(e => \({ to: e.to, subject: e.subject, created_at: e.created_at, last_event: e.last_event }\)\);
    console.log\(JSON.stringify\(list, null, 1\)\);
  }\)
  .catch\(e => console.error\('ERR', e.message\)\);
")

